	@Test
	void defaultEnginePartitionsDistinctWhenTheLeadingJoinPatternProvidesOrder() {
		openRepository(false);
		try (RepositoryConnection connection = repository.getConnection()) {
			IRI seed = iri("seed");
			IRI detail = iri("detail");
			IRI fixed = iri("fixed");
			IRI first = iri("first-owner");
			IRI second = iri("second-owner");
			IRI red = iri("red");
			IRI blue = iri("blue");
			IRI firstGraph = iri("graph-0");
			IRI secondGraph = iri("graph-1");
			connection.begin();
			connection.add(first, seed, fixed, firstGraph, secondGraph);
			connection.add(second, seed, fixed);
			connection.add(first, detail, red, firstGraph, secondGraph);
			connection.add(first, detail, blue);
			connection.add(second, detail, blue);
			for (int i = 0; i < 64; i++) {
				connection.add(iri("unrelated-owner-" + i), detail, red);
			}
			connection.commit();

			String query = "PREFIX ex: <" + NS + ">\n" + """
					SELECT DISTINCT (?subject AS ?owner) ?value WHERE {
						?subject ex:seed ex:fixed ;
							ex:detail ?value .
					}
					""";
			long before = LmdbPartitionedDistinctSteps.partitionedEvaluationCount();
			assertThat(QueryResults.asList(connection.prepareTupleQuery(query).evaluate()))
					.extracting(row -> row.getValue("owner"), row -> row.getValue("value"))
					.containsExactlyInAnyOrder(tuple(first, red), tuple(first, blue), tuple(second, blue));
			assertThat(LmdbPartitionedDistinctSteps.partitionedEvaluationCount() - before)
					.as("default-engine partitioned DISTINCT executions")
					.isEqualTo(1);
		}
	}

	@ParameterizedTest(name = "projection and group aliases with native evaluation {0}")
	@ValueSource(booleans = { false, true })
	void preservesProjectionAndGroupAliases(boolean nativeEvaluation) {
		openRepository(nativeEvaluation);
		try (RepositoryConnection connection = repository.getConnection()) {
			assertThat(QueryResults.asList(connection.prepareTupleQuery(
					"SELECT DISTINCT (?p AS ?predicate) WHERE { ?s ?p ?o }").evaluate()))
							.extracting(row -> row.getValue("predicate"))
							.containsExactlyInAnyOrder(RDF.TYPE, PROPERTY, DEFAULT_PROPERTY, INFERRED_PROPERTY);

			Literal one = VF.createLiteral("1", XSD.INTEGER);
			var grouped = connection.prepareTupleQuery("""
					SELECT (?type AS ?class) (COUNT(DISTINCT ?type) AS ?count) (COUNT(DISTINCT ?type) AS ?again)
					WHERE { ?s a ?type }
					GROUP BY ?type
					""");
			assertThat(QueryResults.asList(grouped.evaluate()))
					.extracting(row -> row.getValue("class"), row -> row.getValue("count"),
							row -> row.getValue("again"))
					.containsExactlyInAnyOrder(tuple(PERSON, one, one), tuple(MACHINE, one, one),
							tuple(INFERRED_TYPE, one, one));
		}
	}

	@Test
	void distinctProjectionCanUseAnIndexInTheOppositeFieldOrder() {
		openRepository(false);
		try (RepositoryConnection connection = repository.getConnection()) {
			String query = "SELECT DISTINCT ?o ?p WHERE { ?s ?p ?o }";
			IRI object = iri("object");
			PrefixWork before = PrefixWork.current();
			try (var rows = connection.prepareTupleQuery(query).evaluate()) {
				assertThat(rows.getBindingNames()).containsExactly("o", "p");
				assertThat(QueryResults.asList(rows)).extracting(row -> row.getValue("o"), row -> row.getValue("p"))
						.containsExactlyInAnyOrder(tuple(PERSON, RDF.TYPE), tuple(MACHINE, RDF.TYPE),
								tuple(INFERRED_TYPE, RDF.TYPE), tuple(object, PROPERTY),
								tuple(object, DEFAULT_PROPERTY), tuple(object, INFERRED_PROPERTY));
			}
			before.assertSkippedRows("DISTINCT object and predicate", false, PROPERTY_ROWS);

			long opened = LmdbPrefixRunPlan.OPENED.get();
			assertThat(QueryResults.asList(connection.prepareTupleQuery(query + " LIMIT 0").evaluate())).isEmpty();
			assertThat(LmdbPrefixRunPlan.OPENED.get()).as("LIMIT 0 opened no prefix cursors").isEqualTo(opened);
		}
	}

	private void openRepository(boolean nativeEvaluation) {
		openRepository(new LmdbStoreConfig().setNativeEvaluationEnabled(nativeEvaluation));
	}

	private void openRepository(LmdbStoreConfig config) {
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		assertThat(store.isExperimentalQueryOptimizations()).isFalse();
		repository = new SailRepository(store);
		repository.init();

		Resource[] graphs = IntStream.range(0, CONTEXTS).mapToObj(i -> iri("graph-" + i)).toArray(Resource[]::new);
		IRI object = iri("object");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int i = 0; i < SUBJECTS; i++) {
				connection.add(iri("subject-" + i), RDF.TYPE, PERSON, graphs);
			}
			for (int i = 0; i < PROPERTY_ROWS; i++) {
				connection.add(iri("property-subject-" + i), PROPERTY, object, graphs[0]);
			}
			connection.add(iri("subject-0"), RDF.TYPE, MACHINE);
			connection.add(iri("subject-1"), RDF.TYPE, MACHINE);
			connection.add(iri("subject-0"), DEFAULT_PROPERTY, object);
			connection.commit();
		}
		try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
			connection.begin();
			IRI inferredGraph = iri("inferred-graph");
			connection.addInferredStatement(iri("subject-0"), RDF.TYPE, PERSON, inferredGraph);
			connection.addInferredStatement(iri("inferred-person"), RDF.TYPE, PERSON, inferredGraph);
			connection.addInferredStatement(iri("inferred-person"), RDF.TYPE, INFERRED_TYPE, inferredGraph);
			connection.addInferredStatement(iri("inferred-person"), INFERRED_PROPERTY, object, inferredGraph);
			connection.commit();
		}
	}

	private static IRI iri(String name) {
		return VF.createIRI(NS, name);
	}

	private static List<Value> predicates(TupleQuery query) {
		return QueryResults.asList(query.evaluate()).stream().map(row -> row.getValue("p")).toList();
	}

	private static Map<Value, Long> counts(TupleQuery query) {
		return QueryResults.asList(query.evaluate())
				.stream()
				.collect(Collectors.toMap(row -> row.getValue("type"), row -> {
					Literal count = (Literal) row.getValue("count");
					assertThat(count.getDatatype()).isEqualTo(XSD.INTEGER);
					return count.longValue();
				}));
	}

	private static Map<Value, Long> allTypes() {
		return Map.of(PERSON, SUBJECTS + 1L, MACHINE, 2L, INFERRED_TYPE, 1L);
	}

	private record PrefixWork(long opened, long rowsScanned) {
		static PrefixWork current() {
			return new PrefixWork(LmdbPrefixRunPlan.OPENED.get(), LmdbPrefixRunPlan.ROWS_SCANNED.get());
		}

		void assertSkippedRows(String query, boolean nativeEvaluation, long denseRows) {
			PrefixWork after = current();
			long openedDelta = after.opened - opened;
			long rowsScannedDelta = after.rowsScanned - rowsScanned;
			System.out.printf("%s (native=%s) prefixCursors=%d sourceRowsScanned=%d denseRows=%d%n",
					query, nativeEvaluation, openedDelta, rowsScannedDelta, denseRows);
			assertThat(openedDelta).as("executed LMDB prefix-run cursors").isPositive();
			assertThat(rowsScannedDelta).as("physical rows visited by the prefix runs")
					.isPositive()
					.isLessThan(denseRows);
		}
	}
